import { icon } from './icons.js';

const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const E = escapeHTML;
const categories = {study:'Học tập',work:'Công việc',personal:'Cá nhân'};
const statuses = {todo:'Cần làm',in_progress:'Đang làm',done:'Hoàn thành'};
const priorities = {high:'Cao',medium:'Vừa',low:'Thấp'};
const repeats = {none:'Không lặp',daily:'Hằng ngày',weekdays:'Thứ 2 – Thứ 6',weekly:'Hằng tuần',monthly:'Hằng tháng'};
const viewNames = {today:'Hôm nay',all:'Tất cả công việc',planner:'Lịch tuần',board:'Bảng tiến độ',matrix:'Ma trận ưu tiên',focus:'Tập trung',stats:'Thống kê'};
const state = {tasks:[],settings:{},focus:{active:null,sessions:[]},today:'',view:'today',storage:'',demoData:false,clockOffset:0,
  filters:{query:'',status:'all',category:'all',priority:'all',sort:'smart'},week:'',statsDays:7,stats:null,
  suggestions:null,suggestionDate:null,suggestionToken:0,quickDraft:'',formSubtasks:[],toastTimer:null,finishing:false,nextFocusRetry:0,breakUntil:0,loadToken:0,focusDraft:{taskId:'',minutes:null}};
let activeDialogTask = null;
let returnFocus = null;
let lastAnnouncement = '';

function dateKey(date = new Date()) {
  const parts = new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date);
  return ['year','month','day'].map(k=>parts.find(p=>p.type===k).value).join('-');
}
function plusDays(date, days) { const d=new Date(`${date}T12:00:00+07:00`);d.setUTCDate(d.getUTCDate()+days);return dateKey(d); }
function monday(date) { const d=new Date(`${date}T12:00:00+07:00`);const wd=d.getUTCDay();return plusDays(date,1-(wd||7)); }
function fmtDate(date, full=false) {return date ? new Intl.DateTimeFormat('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',day:'2-digit',month:'2-digit',...(full?{year:'numeric'}:{})}).format(new Date(`${date}T12:00:00+07:00`)) : 'Chưa có hạn';}
function fmtDuration(minutes) { if(minutes>0&&minutes<1)return 'Dưới 1 phút';const n=Math.round(minutes||0);return n>=60 ? `${Math.floor(n/60)} giờ${n%60?` ${n%60} phút`:''}`:`${n} phút`; }
function weekday(date, short=false) {return new Intl.DateTimeFormat('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',weekday:short?'short':'long'}).format(new Date(`${date}T12:00:00+07:00`));}
function openTasks(){return state.tasks.filter(t=>!t.deletedAt);}
function taskById(id){return state.tasks.find(t=>t.id===id);}
function overdue(t){return t.status!=='done'&&t.dueDate&&t.dueDate<state.today;}
function urgent(t){return Boolean(t.dueDate&&t.dueDate<=plusDays(state.today,1));}
function plannedToday(t){return t.plannedDate===state.today||(!t.plannedDate&&t.dueDate===state.today);}
function selectOptions(values, selected, allLabel) {
  return (allLabel?`<option value="all">${E(allLabel)}</option>`:'')+Object.entries(values).map(([k,v])=>`<option value="${k}"${selected===k?' selected':''}>${E(v)}</option>`).join('');
}
async function api(path,method='GET',body) {
  let res;
  try {res=await fetch(`/api${path}`,{method,headers:body===undefined?{}:{'Content-Type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)})});}
  catch {throw new Error('Chưa kết nối được máy chủ. Kiểm tra terminal chạy node server.js rồi thử lại.');}
  const data=await res.json().catch(()=>({error:'Máy chủ trả về dữ liệu không hợp lệ.'}));
  if(!res.ok) throw new Error(data.error||`Yêu cầu không thành công (${res.status}).`);
  return data;
}
function toast(message, action) {
  const host=$('#toast');clearTimeout(state.toastTimer);
  host.innerHTML=`<span>${E(message)}</span>${action?`<button type="button" data-action="${E(action.type)}" data-id="${E(action.id||'')}">${E(action.label)}</button>`:''}`;
  host.classList.add('is-visible');
  state.toastTimer=setTimeout(()=>host.classList.remove('is-visible'),action?10000:5500);
}
function showError(err){toast(err.message||String(err));}
function announce(message){if(lastAnnouncement!==message){lastAnnouncement=message;toast(message);}}
function showDialog(html, focusSelector) {
  if(!$('#dialog').open) returnFocus=document.activeElement;
  $('#dialogBody').innerHTML=html;
  $('#dialog').setAttribute('aria-labelledby','dialogTitle');
  if(!$('#dialog').open) $('#dialog').showModal();
  if(focusSelector) requestAnimationFrame(()=>$(focusSelector,$('#dialogBody'))?.focus());
}
function closeDialog(){ $('#dialog').close();activeDialogTask=null;returnFocus?.isConnected&&returnFocus.focus(); }
function empty(title,description,button=true){return `<div class="empty-state">${icon('check')}<h3>${E(title)}</h3><p>${E(description)}</p>${button?'<button class="btn btn-secondary" data-action="add">Thêm công việc</button>':''}</div>`;}
function pageIntro(eyebrow,title,lead,actions='') {return `<div class="page-intro"><div><p class="eyebrow">${E(eyebrow)}</p><h1>${E(title)}</h1><p class="lead">${E(lead)}</p></div>${actions?`<div class="page-actions">${actions}</div>`:''}</div>`;}

async function refresh(render=true) {
  const response=await api('/state');
  state.tasks=response.tasks;state.settings=response.settings;state.focus=response.focus;state.storage=response.storage;state.demoData=Boolean(response.demoData);
  state.today=response.today;state.clockOffset=new Date(response.now).getTime()-Date.now();
  if(!state.week)state.week=monday(state.today);
  updateShell();if(render)renderView();
}
function updateShell(){
  $('#profileName').textContent=state.settings.name||'Huy';
  $('#storageLabel').textContent=`${state.storage} · Đã lưu trên máy`;
  $('#headerDate').textContent=`${weekday(state.today)}, ${fmtDate(state.today,true)}`;
  if($('#todayCount'))$('#todayCount').textContent=openTasks().filter(t=>plannedToday(t)&&t.status!=='done').length;
  if($('#allCount'))$('#allCount').textContent=openTasks().filter(t=>t.status!=='done').length;
  $('#breadcrumb').textContent=viewNames[state.view];
  $$('#nav a').forEach(a=>{const current=a.hash===`#${state.view}`;a.classList.toggle('is-active',current);current?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current');});
  const active=state.focus.active;
  const focusNav=$('#nav a[href="#focus"]');if(focusNav)focusNav.classList.toggle('has-active-timer',!!active);
}
function filtered(tasks){
  const f=state.filters,q=normalize(f.query);
  const result=tasks.filter(t=>(!q||normalize([t.title,t.description,...(t.tags||[])].join(' ')).includes(q))&&
    (f.status==='all'||t.status===f.status)&&(f.category==='all'||t.category===f.category)&&(f.priority==='all'||t.priority===f.priority));
  return result.sort((a,b)=>{
    if(f.sort==='title')return a.title.localeCompare(b.title,'vi');
    if(f.sort==='newest')return b.createdAt.localeCompare(a.createdAt);
    if(f.sort==='deadline')return (a.dueDate||'9999').localeCompare(b.dueDate||'9999');
    if(f.sort==='duration')return a.estimateMinutes-b.estimateMinutes;
    const rank={in_progress:0,todo:1,done:2},pr={high:0,medium:1,low:2};
    return rank[a.status]-rank[b.status]||Number(overdue(b))-Number(overdue(a))||(a.scheduledTime||'99').localeCompare(b.scheduledTime||'99')||pr[a.priority]-pr[b.priority]||(a.dueDate||'9999').localeCompare(b.dueDate||'9999');
  });
}
function normalize(text){return String(text).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d');}
function toolbar(){return `<div class="toolbar"><label class="search-field">${icon('search')}<input id="taskSearch" type="search" placeholder="Tìm tên, ghi chú, nhãn…" aria-label="Tìm công việc" value="${E(state.filters.query)}" autocomplete="off"><kbd>/</kbd></label><div class="filters"><label><span class="sr-only">Trạng thái</span><select data-filter="status">${selectOptions(statuses,state.filters.status,'Mọi trạng thái')}</select></label><label><span class="sr-only">Nhóm công việc</span><select data-filter="category">${selectOptions(categories,state.filters.category,'Mọi nhóm')}</select></label><label><span class="sr-only">Độ ưu tiên</span><select data-filter="priority">${selectOptions(priorities,state.filters.priority,'Mọi ưu tiên')}</select></label><label><span class="sr-only">Sắp xếp</span><select data-filter="sort">${selectOptions({smart:'Sắp xếp gợi ý',deadline:'Hạn gần nhất',newest:'Mới nhất',title:'Tên A–Z',duration:'Thời lượng tăng'},state.filters.sort)}</select></label></div></div>`;}
function quickAdd(){return `<form class="quick-add" id="quickAddForm"><span class="quick-add-icon">${icon('plus')}</span><input id="quickInput" name="quick" aria-label="Thêm nhanh công việc" placeholder="Bạn muốn làm gì?" value="${E(state.quickDraft)}" maxlength="400" required autocomplete="off"><button class="btn btn-secondary btn-small" type="submit">Thêm nhanh</button></form><details class="quick-hint"><summary>Thử nhập: Ôn JavaScript ngày mai 30p !1 #học</summary><p>Hỗ trợ hôm nay / ngày mai / YYYY-MM-DD, !1–!3, 30p / 1h, @09:00, #học / #work / #cá-nhân và lặp:hàng-ngày / lặp:hàng-tuần. Bạn sẽ xem và sửa lại trước khi lưu.</p></details>`;}
function taskMeta(t){
  const done=t.subtasks.filter(s=>s.done).length;
  return `<span class="badge category-${t.category}">${E(categories[t.category])}</span><span class="task-time">${icon('clock')}${t.estimateMinutes}p</span>${t.scheduledTime?`<span class="task-time">${E(t.scheduledTime)}</span>`:''}${t.dueDate?`<span class="deadline-text ${overdue(t)?'overdue':''}">${overdue(t)?'Quá hạn':'Hạn'} ${fmtDate(t.dueDate)}</span>`:''}${t.subtasks.length?`<span class="task-subprogress" title="Việc nhỏ đã xong">${icon('list')}${done}/${t.subtasks.length}</span>`:''}${t.repeat!=='none'?`<span title="${E(repeats[t.repeat])}">${icon('repeat')}</span>`:''}${(t.tags||[]).slice(0,2).map(tag=>`<span class="task-tag">#${E(tag)}</span>`).join('')}`;
}
function taskRow(t,{compact=false,showPlan=false}={}){
  return `<article class="task-row ${t.status==='done'?'task-done':''} ${t.status==='in_progress'?'task-in-progress':''}" data-task="${E(t.id)}"><button type="button" class="task-check ${t.status==='done'?'is-checked':''}" data-action="toggle" data-id="${E(t.id)}" aria-label="${t.status==='done'?'Mở lại':'Hoàn thành'} ${E(t.title)}" aria-pressed="${t.status==='done'}">${t.status==='done'?icon('check'):''}</button><div class="task-copy"><button type="button" class="task-title task-title-btn" data-action="edit" data-id="${E(t.id)}">${E(t.title)}</button><div class="task-meta">${taskMeta(t)}${showPlan&&t.plannedDate?`<span>Dự định ${fmtDate(t.plannedDate)}</span>`:''}</div></div><span class="badge priority-${t.priority}">${E(priorities[t.priority])}</span><div class="task-actions"><button class="icon-btn ${t.topDate===state.today?'is-starred':''}" data-action="top" data-id="${E(t.id)}" aria-label="${t.topDate===state.today?'Bỏ khỏi':'Thêm vào'} Top 3 hôm nay: ${E(t.title)}" aria-pressed="${t.topDate===state.today}" title="Top 3 hôm nay">${icon('star')}</button>${t.status!=='done'?`<button class="icon-btn" data-action="focus-task" data-id="${E(t.id)}" aria-label="Tập trung làm ${E(t.title)}" title="Tập trung">${icon('play')}</button>`:''}<button class="icon-btn" data-action="edit" data-id="${E(t.id)}" aria-label="Chỉnh sửa ${E(t.title)}" title="Chỉnh sửa">${icon('edit')}</button></div></article>`;
}
function resultRows(tasks,options){const list=filtered(tasks);return list.length?`<div class="task-list">${list.map(t=>taskRow(t,options)).join('')}</div>`:empty('Chưa có công việc phù hợp','Thử đổi bộ lọc hoặc thêm một việc mới.',true);}
function filterCount(tasks){return `${filtered(tasks).length} / ${tasks.length} công việc`;}

function renderToday(){
  const all=openTasks(),today=all.filter(plannedToday),done=today.filter(t=>t.status==='done'),pending=today.filter(t=>t.status!=='done');
  const late=all.filter(overdue),top=all.filter(t=>t.topDate===state.today),capacity=state.settings.dailyCapacityMinutes;
  const workload=pending.reduce((n,t)=>n+t.estimateMinutes,0),pct=today.length?Math.round(done.length/today.length*100):0;
  const booked=all.filter(t=>t.plannedDate===state.today).reduce((n,t)=>n+t.estimateMinutes,0);
  const greeting=new Intl.DateTimeFormat('en-GB',{hour:'numeric',hourCycle:'h23',timeZone:'Asia/Ho_Chi_Minh'}).format(new Date())<12?'Chào buổi sáng': 'Một ngày của bạn';
  return `${pageIntro(`${greeting}, ${state.settings.name||'Huy'}`,'Từng việc nhỏ. Một ngày tốt.','Chọn điều quan trọng, dành thời gian cho nó, rồi đánh dấu hoàn thành.')}<div class="summary-strip"><div class="summary-item"><strong class="summary-value">${today.length.toString().padStart(2,'0')}</strong><span class="summary-label">việc hôm nay</span></div><div class="summary-item"><strong class="summary-value">${done.length.toString().padStart(2,'0')}</strong><span class="summary-label">đã hoàn thành</span></div><div class="summary-item"><strong class="summary-value">${fmtDuration(workload)}</strong><span class="summary-label">dự kiến còn lại</span></div><div class="summary-item"><strong class="summary-value ${late.length?'text-rust':''}">${late.length.toString().padStart(2,'0')}</strong><span class="summary-label">việc quá hạn</span></div></div><div class="workspace-grid"><div class="workspace-primary"><section class="section-block"><div class="section-head"><div><p class="eyebrow">Giữ sự tập trung</p><h2 class="section-title">Ba việc quan trọng</h2></div><span class="section-meta">${top.length}/3 đã chọn</span></div><div class="top-three">${[0,1,2].map((i)=>top[i]?`<div class="top-item ${top[i].status==='done'?'task-done':''}"><span class="top-number">0${i+1}</span><button class="task-title-btn" data-action="edit" data-id="${E(top[i].id)}">${E(top[i].title)}</button><button class="icon-btn is-starred" data-action="top" data-id="${E(top[i].id)}" title="Bỏ khỏi Top 3" aria-label="Bỏ ${E(top[i].title)} khỏi Top 3">${icon(top[i].status==='done'?'check':'star')}</button></div>`:`<button class="top-item top-empty" data-action="pick-top"><span class="top-number">0${i+1}</span><span>Chọn một việc đáng ưu tiên</span>${icon('plus')}</button>`).join('')}</div></section><section class="section-block"><div class="section-head"><h2 class="section-title">Danh sách hôm nay</h2><span class="section-meta" id="resultCount">${filterCount(today)}</span></div>${quickAdd()}${toolbar()}<div id="taskResults">${resultRows(today)}</div></section>${late.length?`<details class="section-block overdue-section" open><summary class="section-head"><h2 class="section-title">Đừng để bỏ quên <span class="board-count">${late.length}</span></h2><span class="section-meta">Việc đã quá hạn</span></summary><p class="inline-note">Đổi ngày dự định để sắp xếp lại; hạn chót được giữ riêng để bạn theo dõi.</p><div class="task-list">${late.map(t=>taskRow(t,{compact:true})).join('')}</div></details>`:''}</div><aside class="workspace-aside"><section class="note-panel daily-note"><p class="eyebrow">NHỊP ĐỘ HÔM NAY</p><div class="daily-progress-number">${pct}<span>%</span></div><div class="progress-track" role="progressbar" aria-label="Tiến độ công việc hôm nay" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}"><div class="progress-fill" style="width:${pct}%"></div></div><p>${done.length} trên ${today.length} việc đã xong.</p><p class="inline-note">Một việc hoàn thành cũng là một bước tiến.</p></section><section class="note-panel"><div class="section-head"><h2 class="section-title">Quỹ thời gian</h2>${icon('clock')}</div><div class="workload-label"><strong>${fmtDuration(booked)}</strong><span>/ ${fmtDuration(capacity)}</span></div><div class="progress-track"><div class="progress-fill ${booked>capacity?'is-overloaded':''}" style="width:${Math.min(100,Math.round(booked/capacity*100))}%"></div></div><p class="${booked>capacity?'capacity-warning':'inline-note'}">${booked>capacity?`Lịch đang vượt ${fmtDuration(booked-capacity)}. Cân nhắc chuyển bớt việc sang ngày khác.`:`Còn ${fmtDuration(Math.max(0,capacity-booked))} chưa được lên kế hoạch hôm nay.`}</p><p class="inline-note">Tính cả việc đã xong trong kế hoạch ngày.</p><button class="btn btn-ghost btn-small" data-action="settings">Điều chỉnh quỹ thời gian</button></section><section class="note-panel suggestions-panel"><div class="section-head"><h2 class="section-title">Gợi ý tiếp theo</h2>${icon('light')}</div><p class="inline-note">Xếp theo hạn chót, mức ưu tiên và thời gian còn trống.</p><div id="suggestionsBody"><button class="btn btn-secondary" data-action="suggest" data-date="${state.today}">Tìm việc phù hợp</button></div></section><div class="aside-footer">Làm từng việc một.<br>Cho điều quan trọng một chỗ trong ngày.</div></aside></div>`;
}
function renderAll(){const tasks=openTasks();return `${pageIntro('Không gian công việc','Mọi điều cần làm.','Một nơi cho bài tập, dự án và những việc riêng của bạn.',`<button class="btn btn-ghost" data-action="trash">${icon('trash')}Thùng rác</button>`)}${quickAdd()}${toolbar()}<div class="section-head"><h2 class="section-title">Công việc của bạn</h2><span class="section-meta" id="resultCount">${filterCount(tasks)}</span></div><div id="taskResults">${resultRows(tasks,{showPlan:true})}</div>`;}
function boardCard(t){return `<article class="board-card" draggable="true" data-drag-id="${E(t.id)}"><div class="board-card-top"><span class="badge priority-${t.priority}">${E(priorities[t.priority])}</span><span class="drag-handle" title="Kéo sang cột khác">${icon('grip')}</span></div><button class="task-title-btn" data-action="edit" data-id="${E(t.id)}">${E(t.title)}</button>${t.description?`<p class="board-description">${E(t.description.slice(0,100))}${t.description.length>100?'…':''}</p>`:''}<div class="task-meta">${taskMeta(t)}</div><div class="board-card-bottom"><label class="sr-only" for="status-${E(t.id)}">Trạng thái ${E(t.title)}</label><select id="status-${E(t.id)}" class="status-select" data-task-status="${E(t.id)}">${selectOptions(statuses,t.status)}</select><button class="icon-btn" data-action="edit" data-id="${E(t.id)}" aria-label="Sửa ${E(t.title)}">${icon('edit')}</button></div></article>`;}
function boardColumns(){const tasks=filtered(openTasks());return Object.entries(statuses).map(([status,label])=>{const list=tasks.filter(t=>t.status===status);return `<section class="board-column" data-drop-status="${status}"><div class="board-head"><h2>${E(label)}</h2><span class="board-count">${list.length}</span></div><div class="board-tasks">${list.map(boardCard).join('')||'<p class="drop-placeholder">Kéo công việc vào đây</p>'}</div><button class="btn btn-ghost" data-action="add" data-status="${status}">${icon('plus')}Thêm công việc</button></section>`;}).join('');}
function renderBoard(){return `${pageIntro('Theo dõi quá trình','Công việc đang ở đâu?','Kéo công việc giữa các cột, hoặc đổi trạng thái bằng ô chọn trên từng việc.')} ${toolbar()}<div class="board" id="boardContent">${boardColumns()}</div>`;}
function matrixQuadrants(){const tasks=filtered(openTasks().filter(t=>t.status!=='done'));const quadrants=[{name:'Làm ngay',subtitle:'Quan trọng · Khẩn cấp',important:true,urgent:true},{name:'Lên kế hoạch',subtitle:'Quan trọng · Chưa khẩn cấp',important:true,urgent:false},{name:'Xử lý gọn',subtitle:'Ít quan trọng · Khẩn cấp',important:false,urgent:true},{name:'Cân nhắc lại',subtitle:'Ít quan trọng · Chưa khẩn cấp',important:false,urgent:false}];return quadrants.map((q,i)=>{const list=tasks.filter(t=>t.important===q.important&&urgent(t)===q.urgent);return `<section class="quadrant q${i+1}"><div class="quadrant-head"><div><p class="eyebrow">${q.subtitle}</p><h2>${q.name}</h2></div><span class="board-count">${list.length}</span></div><div class="quadrant-tasks">${list.map(t=>`<div class="matrix-task"><button class="task-check" data-action="toggle" data-id="${E(t.id)}" aria-label="Hoàn thành ${E(t.title)}"></button><div><button class="task-title-btn" data-action="edit" data-id="${E(t.id)}">${E(t.title)}</button><div class="task-meta"><span>${t.dueDate?`Hạn ${fmtDate(t.dueDate)}`:'Chưa có hạn'}</span><span>${t.estimateMinutes}p</span></div></div><button class="icon-btn ${t.important?'is-starred':''}" data-action="important" data-id="${E(t.id)}" title="Đổi mức quan trọng" aria-label="${t.important?'Bỏ':'Đánh dấu'} quan trọng: ${E(t.title)}">${icon('flag')}</button></div>`).join('')||'<p class="inline-note quadrant-empty">Chưa có công việc trong nhóm này.</p>'}</div></section>`;}).join('');}
function renderMatrix(){return `${pageIntro('Ma trận Eisenhower','Bận rộn, hay đúng việc?','Phân biệt việc quan trọng với việc cần xử lý gấp để chọn hành động phù hợp.')}<p class="rule-note">${icon('info')} “Quan trọng” do bạn đánh dấu. “Khẩn cấp” là việc có hạn vào ngày mai, hôm nay hoặc đã quá hạn. Chỉ hiển thị việc chưa hoàn thành.</p>${toolbar()}<div class="matrix" id="matrixContent">${matrixQuadrants()}</div>`;}

function renderPlanner(){
  const dates=Array.from({length:7},(_,i)=>plusDays(state.week,i)),tasks=openTasks();
  const unplanned=tasks.filter(t=>!t.plannedDate&&t.status!=='done');
  return `${pageIntro('Dành chỗ cho điều quan trọng','Một tuần, có chủ đích.','Kéo việc chưa có lịch vào một ngày. Bấm vào công việc để đặt giờ và thời lượng.')}<div class="planner-toolbar"><div class="week-navigation"><button class="icon-btn" data-action="week-prev" aria-label="Tuần trước">${icon('chevronLeft')}</button><strong>${fmtDate(dates[0])} – ${fmtDate(dates[6],true)}</strong><button class="icon-btn" data-action="week-next" aria-label="Tuần sau">${icon('chevronRight')}</button><button class="btn btn-ghost btn-small" data-action="week-today">Tuần này</button></div><span class="inline-note">Giờ Việt Nam · ${E(state.settings.dayStart)}–${E(state.settings.dayEnd)}</span></div><div class="week-grid">${dates.map(date=>{const list=tasks.filter(t=>t.plannedDate===date).sort((a,b)=>(a.scheduledTime||'99').localeCompare(b.scheduledTime||'99'));const mins=list.reduce((n,t)=>n+t.estimateMinutes,0);return `<section class="day-column ${date===state.today?'is-today':''}" data-drop-date="${date}"><div class="day-head"><span>${weekday(date,true)}</span><strong>${Number(date.slice(-2))}</strong><span class="day-workload ${mins>state.settings.dailyCapacityMinutes?'overdue':''}">${mins} / ${state.settings.dailyCapacityMinutes}p</span></div><div class="day-tasks">${list.map(t=>`<article class="schedule-item ${t.status==='done'?'task-done':''}" draggable="true" data-drag-id="${E(t.id)}"><span class="schedule-time">${t.scheduledTime||'Chưa đặt giờ'} · ${t.estimateMinutes}p</span><button class="task-title-btn" data-action="edit" data-id="${E(t.id)}">${E(t.title)}</button><span class="badge category-${t.category}">${E(categories[t.category])}</span></article>`).join('')||'<span class="drop-placeholder">Một khoảng trống cho bạn</span>'}</div><div class="day-footer"><button class="icon-btn" data-action="add" data-date="${date}" title="Thêm việc vào ngày này" aria-label="Thêm việc ngày ${fmtDate(date)}">${icon('plus')}</button><button class="btn btn-ghost btn-small" data-action="suggest-planner" data-date="${date}">Gợi ý lịch</button></div></section>`;}).join('')}</div><section class="section-block"><div class="section-head"><h2 class="section-title">Chưa có ngày dự định</h2><span class="section-meta">${unplanned.length} công việc</span></div><p class="inline-note">Kéo vào lịch hoặc bấm chỉnh sửa để chọn ngày. Đổi ngày trong lịch giữ nguyên hạn chót.</p><div class="unscheduled-list">${unplanned.map(t=>`<article class="unscheduled-item" draggable="true" data-drag-id="${E(t.id)}">${icon('grip')}<button class="task-title-btn" data-action="edit" data-id="${E(t.id)}">${E(t.title)}</button><span>${t.estimateMinutes}p</span>${t.dueDate?`<span class="${overdue(t)?'overdue':''}">Hạn ${fmtDate(t.dueDate)}</span>`:''}</article>`).join('')||'<p class="inline-note">Tất cả công việc đang mở đã có ngày dự định.</p>'}</div></section>`;
}
function focusElapsed(active){if(!active)return 0;return Math.min(active.plannedMinutes*60,Math.max(0,(active.elapsedSeconds||0)+(active.status==='running'&&active.anchorAt?(Date.now()+state.clockOffset-new Date(active.anchorAt).getTime())/1000:0)));}
function sessionRows(sessions){return sessions.length?sessions.map(s=>`<div class="session-row"><span class="session-marker">${icon('check')}</span><div><strong>${E(s.taskTitle||'Phiên tập trung tự do')}</strong><span>${new Intl.DateTimeFormat('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(s.finishedAt))} · ${s.status==='completed'?'Đủ thời lượng':'Kết thúc sớm'}</span></div><strong>${Math.floor(s.elapsedSeconds/60)}p ${Math.floor(s.elapsedSeconds%60)}s</strong></div>`).join(''):'<p class="inline-note">Phiên tập trung hoàn tất sẽ xuất hiện tại đây.</p>';}
function renderFocus(){const active=state.focus.active,pending=openTasks().filter(t=>t.status!=='done'),sessions=[...state.focus.sessions].sort((a,b)=>b.finishedAt.localeCompare(a.finishedAt)).slice(0,10);return `${pageIntro('Một việc trong một thời điểm','Cho tâm trí một khoảng yên.','Chọn công việc, đặt hẹn giờ và dành trọn sự chú ý. Thời gian thực tế được ghi lại.')}<div class="focus-layout"><section class="focus-stage"><p class="eyebrow" id="focusModeLabel">${active?(active.status==='paused'?'ĐANG TẠM DỪNG':'ĐANG TẬP TRUNG'):'SẴN SÀNG BẮT ĐẦU'}</p><div class="timer-ring"><svg viewBox="0 0 280 280" aria-hidden="true"><circle class="timer-track" cx="140" cy="140" r="126"/><circle id="timerProgress" class="timer-arc" cx="140" cy="140" r="126" stroke-dasharray="791.68" stroke-dashoffset="0"/></svg><div class="timer-center"><div class="timer-display" id="timerDisplay" role="timer" aria-label="Thời gian còn lại">${String(active?.plannedMinutes||state.focusDraft.minutes||state.settings.focusMinutes).padStart(2,'0')}:00</div><span id="timerCaption">${active?'Một bước nữa cho việc quan trọng.':'Tập trung vừa đủ, nghỉ ngơi đúng lúc.'}</span></div></div>${active?`<h2 class="focus-current-task">${E(active.taskTitle||'Tập trung tự do')}</h2><div class="timer-controls"><button class="btn btn-primary" data-action="focus-${active.status==='paused'?'resume':'pause'}">${icon(active.status==='paused'?'play':'pause')}${active.status==='paused'?'Tiếp tục':'Tạm dừng'}</button><button class="btn btn-secondary" data-action="focus-finish">${icon('stop')}Kết thúc & lưu</button><button class="btn btn-ghost" data-action="focus-cancel">Bỏ phiên này</button></div><p class="inline-note">Phiên vẫn được giữ khi tải lại trang. Việc hoàn thành task được đánh dấu riêng.</p>`:`<form id="focusStartForm"><div class="field focus-task-select"><label for="focusTask">Bạn sẽ tập trung vào việc gì?</label><select id="focusTask" name="taskId"><option value="">Tập trung tự do</option>${filtered(pending).map(t=>`<option value="${E(t.id)}"${state.focusDraft.taskId===t.id?' selected':''}>${E(t.title)}</option>`).join('')}</select></div><div class="focus-presets"><button type="button" class="btn btn-ghost btn-small" data-action="focus-preset" data-minutes="25">25 phút</button><button type="button" class="btn btn-ghost btn-small" data-action="focus-preset" data-minutes="50">50 phút</button><label><input id="focusMinutes" name="minutes" type="number" min="1" max="120" value="${state.focusDraft.minutes||state.settings.focusMinutes}" required aria-label="Số phút tập trung"> phút</label></div><div class="timer-controls"><button class="btn btn-primary" type="submit">${icon('play')}Bắt đầu tập trung</button><button class="btn btn-ghost" type="button" data-action="break">Nghỉ ${state.settings.breakMinutes} phút</button></div></form><p class="inline-note">Phiên tập trung được lưu trên máy chủ; hẹn giờ nghỉ chạy trong trình duyệt.</p>`}<p class="break-message" id="breakMessage"></p></section><aside><section class="note-panel"><p class="eyebrow">MỘT GỢI Ý NHỎ</p><h2 class="section-title">Bắt đầu không cần hoàn hảo.</h2><p>Tắt những tab không cần thiết. Chọn một việc vừa sức. Bạn chỉ cần bắt đầu với khoảng thời gian này.</p><div class="focus-session-summary"><strong>${state.focus.sessions.filter(s=>dateKey(new Date(s.finishedAt))===state.today).length}</strong><span>phiên đã lưu hôm nay</span></div></section><section class="focus-log"><div class="section-head"><h2 class="section-title">Những khoảng tập trung</h2></div>${sessionRows(sessions)}</section></aside></div>`;}

function renderStatsContent(s){
  const max=Math.max(1,...s.series.map(d=>d.completed)),maxFocus=Math.max(1,...s.series.map(d=>d.focusMinutes));
  return `<div class="summary-strip"><div class="summary-item"><strong class="summary-value">${s.completionRate}%</strong><span class="summary-label">hoàn thành · ${s.completed}/${s.total} việc</span></div><div class="summary-item"><strong class="summary-value">${s.onTimeEligible?s.onTimeRate+'%':'—'}</strong><span class="summary-label">đúng hạn · ${s.onTimeCompleted}/${s.onTimeEligible} việc có hạn</span></div><div class="summary-item"><strong class="summary-value">${fmtDuration(s.focusMinutes)}</strong><span class="summary-label">tập trung trong ${s.days} ngày</span></div><div class="summary-item"><strong class="summary-value">${s.overdue}</strong><span class="summary-label">việc đang quá hạn</span></div></div><div class="stats-grid"><section class="chart-panel"><div class="section-head"><div><p class="eyebrow">NHỊP ĐỘ HOÀN THÀNH</p><h2 class="section-title">Tiến lên từng ngày</h2></div><span class="section-meta">${s.series.reduce((n,d)=>n+d.completed,0)} việc / ${s.days} ngày</span></div><div class="bar-chart ${s.days===30?'is-month':''}" role="img" aria-label="Công việc hoàn thành mỗi ngày, theo ngày hoàn thành thực tế"><div class="chart-baseline"></div>${s.series.map((d,i)=>`<div class="bar-column" title="${fmtDate(d.date)}: ${d.completed} việc hoàn thành"><span class="bar-value">${d.completed||''}</span><div class="bar ${d.date===state.today?'bar-today':''}" style="height:${Math.max(2,d.completed/max*150)}px" aria-hidden="true"></div><span class="bar-caption">${s.days===7?weekday(d.date,true):(i%5===0||i===s.series.length-1?d.date.slice(-2):'')}</span></div>`).join('')}</div><p class="inline-note">Đếm theo ngày đánh dấu hoàn thành, không theo hạn chót.</p></section><section class="chart-panel"><div class="section-head"><div><p class="eyebrow">PHÂN BỔ CÔNG VIỆC</p><h2 class="section-title">Bạn dành sức cho đâu?</h2></div></div><div class="category-list">${s.categories.map(c=>`<div class="category-stat"><div><span class="badge category-${E(c.key)}">${E(c.label)}</span><span>${c.completed}/${c.total} đã xong</span></div><div class="progress-track"><div class="progress-fill category-fill-${E(c.key)}" style="width:${c.total?c.completed/c.total*100:0}%"></div></div></div>`).join('')}</div><p class="inline-note">Tính trên toàn bộ công việc, không gồm thùng rác.</p></section><section class="chart-panel"><div class="section-head"><div><p class="eyebrow">THỜI GIAN TẬP TRUNG</p><h2 class="section-title">Những phút có ý nghĩa</h2></div><span class="section-meta">${s.focusSessions} phiên đã lưu</span></div><div class="bar-chart ${s.days===30?'is-month':''}" role="img" aria-label="Phút tập trung được ghi lại mỗi ngày">${s.series.map((d,i)=>`<div class="bar-column" title="${fmtDate(d.date)}: ${d.focusMinutes} phút"><span class="bar-value">${d.focusMinutes||''}</span><div class="bar bar-focus" style="height:${Math.max(2,d.focusMinutes/maxFocus*130)}px"></div><span class="bar-caption">${s.days===7?weekday(d.date,true):(i%5===0||i===s.series.length-1?d.date.slice(-2):'')}</span></div>`).join('')}</div><p class="inline-note">Ghi thời gian thực tế khi kết thúc phiên, kể cả phiên kết thúc sớm.</p></section><section class="note-panel insights-panel"><p class="eyebrow">DỪNG LẠI ĐỂ NHÌN LẠI</p><h2 class="section-title">Một vài điều đáng chú ý</h2><ul class="insight-list">${s.insights.map(x=>`<li>${E(x)}</li>`).join('')}</ul><p class="inline-note">Nhận xét được tạo từ các quy tắc và dữ liệu của bạn.</p></section></div><details class="section-block stats-data"><summary>Xem dữ liệu biểu đồ dạng bảng</summary><div class="table-scroll"><table><thead><tr><th>Ngày</th><th>Hoàn thành</th><th>Phút tập trung</th><th>Đã lên kế hoạch</th></tr></thead><tbody>${s.series.map(d=>`<tr><td>${fmtDate(d.date,true)}</td><td>${d.completed}</td><td>${d.focusMinutes}</td><td>${d.planned}</td></tr>`).join('')}</tbody></table></div></details>`;
}
function renderStats(){return `${pageIntro('Nhìn lại để đi tiếp','Tiến bộ có thể nhìn thấy.','Không phải làm nhiều nhất. Là hiểu cách bạn làm việc, rồi điều chỉnh từng chút.',`<div class="segmented" aria-label="Khoảng thời gian thống kê"><button data-action="stats-period" data-days="7" aria-pressed="${state.statsDays===7}">7 ngày</button><button data-action="stats-period" data-days="30" aria-pressed="${state.statsDays===30}">30 ngày</button></div>`)}<div id="statsContent">${state.stats&&state.stats.days===state.statsDays?renderStatsContent(state.stats):'<p class="app-loading" role="status">Đang đọc thống kê…</p>'}</div>`;}

function renderView(){
  const content=$('#content');
  const views={today:renderToday,all:renderAll,planner:renderPlanner,board:renderBoard,matrix:renderMatrix,focus:renderFocus,stats:renderStats};
  content.innerHTML=(state.demoData?'<p class="sample-notice"><strong>Dữ liệu minh họa</strong> Kho này được khởi tạo với task và phiên tập trung mẫu. Thống kê có thể bao gồm các ví dụ đó.</p>':'')+views[state.view]();content.dataset.view=state.view;
  document.title=`${viewNames[state.view]} · TaskFlow`;
  updateShell();updateTimer();
  if(state.view==='stats')loadStats();
}
async function loadStats(){const token=++state.loadToken;try{const result=await api(`/stats?days=${state.statsDays}`);if(token!==state.loadToken||state.view!=='stats')return;state.stats=result.stats||result;$('#statsContent').innerHTML=renderStatsContent(state.stats);}catch(err){if($('#statsContent'))$('#statsContent').innerHTML=`<div class="error-panel"><p>${E(err.message)}</p><button class="btn btn-secondary" data-action="reload">Thử lại</button></div>`;}}
function renderFiltered(){
  if(state.view==='today'||state.view==='all'){const tasks=state.view==='today'?openTasks().filter(plannedToday):openTasks();$('#taskResults').innerHTML=resultRows(tasks,{showPlan:state.view==='all'});$('#resultCount').textContent=filterCount(tasks);}
  else if(state.view==='board')$('#boardContent').innerHTML=boardColumns();
  else if(state.view==='matrix')$('#matrixContent').innerHTML=matrixQuadrants();
}

function subtaskEditor(){return state.formSubtasks.map((s,i)=>`<div class="subtask-row"><input type="checkbox" data-sub-check="${i}" aria-label="Hoàn thành việc nhỏ ${E(s.title)}" ${s.done?'checked':''}><input type="text" data-sub-title="${i}" value="${E(s.title)}" maxlength="160" aria-label="Tên việc nhỏ ${i+1}" required><button type="button" class="icon-btn" data-action="remove-subtask" data-index="${i}" aria-label="Xóa việc nhỏ ${i+1}">${icon('close')}</button></div>`).join('');}
function openTaskForm(id=null,draft={},preview=null){
  const existing=id?taskById(id):null;if(id&&!existing)return;
  const t={title:'',description:'',category:'study',priority:'medium',status:'todo',plannedDate:state.view==='today'?state.today:null,dueDate:null,scheduledTime:null,estimateMinutes:25,important:false,tags:[],repeat:'none',subtasks:[],...existing,...draft};
  activeDialogTask=id;state.formSubtasks=t.subtasks.map(s=>({...s}));
  showDialog(`<div class="modal-head"><p class="eyebrow">${id?'CHỈNH SỬA CÔNG VIỆC':'MỘT VIỆC MỚI'}</p><h2 id="dialogTitle">${id?'Thêm một chút rõ ràng.':'Bạn muốn hoàn thành điều gì?'}</h2><p class="modal-description">Ngày dự định là lúc bạn làm. Hạn chót là lúc việc cần xong.</p></div>${preview?`<div class="rule-note">${icon('info')}<div><strong>Đã đọc: ${E(preview.tokens.join(' · ')||'tiêu đề công việc')}</strong><p>Kiểm tra các trường bên dưới trước khi lưu.${preview.warnings.length?' '+E(preview.warnings.join(' ')):''}</p></div></div>`:''}<form id="taskForm"><div class="form-error" id="taskFormError" role="alert" hidden></div><div class="form-grid"><div class="field span-2"><label for="taskTitle">Tên công việc <span aria-hidden="true">*</span></label><input id="taskTitle" name="title" maxlength="160" required value="${E(t.title)}" placeholder="Ví dụ: Hoàn thiện báo cáo JavaScript"></div><div class="field span-2"><label for="taskDescription">Ghi chú</label><textarea id="taskDescription" name="description" rows="3" maxlength="2000" placeholder="Một vài chi tiết giúp bạn bắt đầu…">${E(t.description)}</textarea></div><div class="field"><label for="taskPlannedDate">Ngày dự định làm</label><input id="taskPlannedDate" name="plannedDate" type="date" value="${E(t.plannedDate||'')}"></div><div class="field"><label for="taskDueDate">Hạn chót</label><input id="taskDueDate" name="dueDate" type="date" value="${E(t.dueDate||'')}"></div><div class="field"><label for="taskTime">Bắt đầu lúc</label><input id="taskTime" name="scheduledTime" type="time" step="300" value="${E(t.scheduledTime||'')}"><small>Đặt cùng ngày dự định. Hệ thống kiểm tra trùng giờ.</small></div><div class="field"><label for="taskEstimate">Thời lượng dự kiến (phút)</label><input id="taskEstimate" name="estimateMinutes" type="number" min="5" max="480" required value="${t.estimateMinutes}"></div><div class="field"><label for="taskCategory">Nhóm công việc</label><select id="taskCategory" name="category">${selectOptions(categories,t.category)}</select></div><div class="field"><label for="taskPriority">Mức ưu tiên</label><select id="taskPriority" name="priority">${selectOptions(priorities,t.priority)}</select></div><div class="field"><label for="taskStatus">Trạng thái</label><select id="taskStatus" name="status">${selectOptions(statuses,t.status)}</select></div><div class="field"><label for="taskRepeat">Lặp lại</label><select id="taskRepeat" name="repeat">${selectOptions(repeats,t.repeat)}</select><small>Tạo lần tiếp theo khi hoàn thành việc này.</small></div><div class="field span-2"><label for="taskTags">Nhãn (ngăn cách bằng dấu phẩy)</label><input id="taskTags" name="tags" value="${E(t.tags.join(', '))}" placeholder="JavaScript, báo cáo, UEH" maxlength="264"></div><div class="field span-2 checkbox-field"><label><input id="taskImportant" name="important" type="checkbox" ${t.important?'checked':''}>Quan trọng với mục tiêu của tôi</label><small>Dùng để phân nhóm trong ma trận ưu tiên; độc lập với mức ưu tiên.</small></div><div class="field span-2"><div class="section-head"><label>Các việc nhỏ</label><span class="section-meta">Tối đa 30 việc</span></div><div class="subtask-editor" id="subtaskEditor">${subtaskEditor()}</div><div class="subtask-add"><input id="newSubtask" placeholder="Chia việc lớn thành bước dễ bắt đầu…" maxlength="160" aria-label="Tên việc nhỏ mới"><button type="button" class="btn btn-secondary btn-small" data-action="add-subtask">${icon('plus')}Thêm</button></div><small>Đánh dấu việc nhỏ không tự động hoàn thành công việc lớn.</small></div></div>${existing?.nextOccurrenceId?'<p class="rule-note">Lần lặp tiếp theo đã được tạo. Mở lại và hoàn thành việc này sẽ không tạo thêm bản trùng.</p>':''}<div class="form-actions">${id?`<button type="button" class="btn btn-ghost btn-danger" data-action="delete" data-id="${E(id)}">${icon('trash')}Xóa</button>`:'<span></span>'}<div><button type="button" class="btn btn-ghost" data-action="close-dialog">Hủy</button><button type="submit" class="btn btn-primary">${id?'Lưu thay đổi':'Tạo công việc'}</button></div></div></form>`,'#taskTitle');
}
async function submitTask(form){
  if(!form.reportValidity())return;
  const editingId=activeDialogTask;
  const data=new FormData(form),button=$('[type="submit"]',form);button.disabled=true;
  const payload={title:data.get('title').trim(),description:data.get('description').trim(),category:data.get('category'),priority:data.get('priority'),status:data.get('status'),plannedDate:data.get('plannedDate')||null,dueDate:data.get('dueDate')||null,scheduledTime:data.get('scheduledTime')||null,estimateMinutes:Number(data.get('estimateMinutes')),important:data.get('important')==='on',repeat:data.get('repeat'),tags:[...new Set(data.get('tags').split(',').map(t=>t.trim().replace(/^#/,'' )).filter(Boolean))],subtasks:state.formSubtasks.map(s=>({...s,title:s.title.trim()}))};
  try{const result=await api(editingId?`/tasks/${editingId}`:'/tasks',editingId?'PATCH':'POST',payload);if(form.isConnected)closeDialog();state.quickDraft='';await refresh();toast(result.generatedTask?'Đã lưu. Lần lặp tiếp theo đã được tạo.':'Đã lưu công việc.');}
  catch(err){const box=form.isConnected?$('#taskFormError',form):null;if(box){box.textContent=err.message;box.hidden=false;box.scrollIntoView({block:'nearest',behavior:'smooth'});}else showError(err);}
  finally{button.disabled=false;}
}
async function patchTask(id,payload,message='Đã cập nhật công việc.') {const result=await api(`/tasks/${id}`,'PATCH',payload);await refresh();toast(result.generatedTask?'Đã hoàn thành và tạo lần lặp tiếp theo.':message);return result;}
function pickTop(){const picked=openTasks().filter(t=>t.topDate===state.today),choices=filtered(openTasks().filter(t=>t.status!=='done'&&t.topDate!==state.today));showDialog(`<div class="modal-head"><p class="eyebrow">TOP 3 HÔM NAY · ${picked.length}/3</p><h2 id="dialogTitle">Việc nào đáng ưu tiên?</h2><p>Chọn tối đa ba việc. Bạn có thể bỏ chọn bằng biểu tượng ngôi sao.</p></div><div class="top-picker">${choices.map(t=>`<button class="top-choice" data-action="pick-top-task" data-id="${E(t.id)}"><span><strong>${E(t.title)}</strong><span>${E(categories[t.category])} · ${t.estimateMinutes}p${t.dueDate?' · Hạn '+fmtDate(t.dueDate):''}</span></span>${icon('star')}</button>`).join('')||empty('Không còn việc để chọn','Thêm công việc mới rồi quay lại đây.',false)}</div>`);}
async function getSuggestions(date,dialog=false){
  const requestToken=++state.suggestionToken;
  state.suggestionDate=date;
  state.suggestions=null;
  if(dialog)showDialog(`<div class="modal-head"><p class="eyebrow">KẾ HOẠCH ${fmtDate(date)}</p><h2 id="dialogTitle">Tìm một lịch vừa sức.</h2></div><div id="suggestionsBody" role="status">Đang kiểm tra khoảng trống…</div>`);
  else $('#suggestionsBody').innerHTML='<p class="inline-note" role="status">Đang kiểm tra khoảng trống…</p>';
  const targetHost=$('#suggestionsBody');
  try{const s=await api(`/suggestions?date=${date}`);if(requestToken!==state.suggestionToken||!targetHost?.isConnected||targetHost!==$('#suggestionsBody'))return;state.suggestions=s;targetHost.innerHTML=`<p class="inline-note">Đã dự kiến ${fmtDuration(s.committedMinutes)} / ${fmtDuration(s.capacityMinutes)}.${s.overloaded?' Ngày này đã vượt quỹ thời gian.':''}</p>${s.items.length?`<div class="suggestion-list">${s.items.map(item=>`<label class="suggestion-item"><input type="checkbox" name="suggestion" value="${E(item.taskId)}" checked><span><strong>${E(taskById(item.taskId)?.title||'Công việc')}</strong><span class="suggestion-reason">${E(item.reason)}</span><span class="suggestion-slot">${E(item.scheduledTime||'Chưa đặt giờ')} · ${item.estimateMinutes}p</span></span></label>`).join('')}</div><button class="btn btn-primary" data-action="apply-suggestions">Áp dụng các việc đã chọn</button>`:'<p class="suggestions-empty">Chưa có việc phù hợp với khoảng trống còn lại. Bạn vẫn có thể xếp lịch thủ công.</p>'}${s.unscheduledCount?`<p class="inline-note">${s.unscheduledCount} việc chưa thể xếp trong lượt gợi ý này.</p>`:''}<p class="rule-note">Gợi ý theo quy tắc, không tự thay đổi lịch. Lịch được kiểm tra lại khi bạn áp dụng.</p>`;}
  catch(err){if(requestToken===state.suggestionToken&&targetHost?.isConnected)targetHost.innerHTML=`<p class="form-error">${E(err.message)}</p>`;}
}

function settingsDialog(){const s=state.settings;showDialog(`<div class="modal-head"><p class="eyebrow">KHÔNG GIAN CỦA BẠN</p><h2 id="dialogTitle">Một nhịp làm việc phù hợp.</h2><p>Tùy chỉnh kế hoạch ngày và giữ một bản sao dữ liệu của bạn.</p></div><form id="settingsForm"><div class="form-error" id="settingsError" role="alert" hidden></div><div class="form-grid"><div class="field"><label for="settingName">Tên hiển thị</label><input name="name" id="settingName" value="${E(s.name)}" maxlength="60" required></div><div class="field"><label for="settingCapacity">Quỹ thời gian mỗi ngày (phút)</label><input name="dailyCapacityMinutes" id="settingCapacity" type="number" min="30" max="720" required value="${s.dailyCapacityMinutes}"></div><div class="field"><label for="settingStart">Ngày làm việc bắt đầu</label><input name="dayStart" id="settingStart" type="time" required value="${E(s.dayStart)}"></div><div class="field"><label for="settingEnd">Ngày làm việc kết thúc</label><input name="dayEnd" id="settingEnd" type="time" required value="${E(s.dayEnd)}"></div><div class="field"><label for="settingFocus">Phiên tập trung mặc định (phút)</label><input name="focusMinutes" id="settingFocus" type="number" min="1" max="120" required value="${s.focusMinutes}"></div><div class="field"><label for="settingBreak">Nghỉ giữa phiên (phút)</label><input name="breakMinutes" id="settingBreak" type="number" min="1" max="30" required value="${s.breakMinutes}"></div></div><p class="inline-note">Múi giờ: Việt Nam (UTC+7). Khung giờ dùng cho gợi ý; bạn vẫn có thể đặt lịch ngoài khung này.</p><div class="form-actions"><span></span><button type="submit" class="btn btn-primary">Lưu tùy chỉnh</button></div></form><section class="section-block"><h3 class="section-title">Dữ liệu của bạn</h3><p>Đang lưu bằng <strong>${state.storage}</strong> trên máy chủ. Xuất bản sao trước khi chuyển máy hoặc nhập dữ liệu.</p><div class="backup-actions"><button class="btn btn-secondary" data-action="export">${icon('download')}Xuất JSON</button><button class="btn btn-secondary" data-action="import">${icon('upload')}Nhập JSON</button><button class="btn btn-ghost" data-action="trash">${icon('trash')}Thùng rác (${state.tasks.filter(t=>t.deletedAt).length})</button><input type="file" id="importFile" accept=".json,application/json" hidden></div><p class="inline-note">Nhập bổ sung TaskFlow V1/V2.5, bỏ qua ID trùng. Không xóa công việc hiện có. Tùy chỉnh hiện tại được giữ nguyên.</p><p class="inline-note">Bản sao không chứa phiên hẹn giờ đang chạy. Hãy kết thúc phiên trước khi chuyển máy.</p></section>`);}
function trashDialog(){const trash=state.tasks.filter(t=>t.deletedAt).sort((a,b)=>b.deletedAt.localeCompare(a.deletedAt));showDialog(`<div class="modal-head"><p class="eyebrow">THÙNG RÁC</p><h2 id="dialogTitle">Vẫn còn ở đây.</h2><p>Công việc đã xóa không tính vào kế hoạch và thống kê. Bạn có thể khôi phục khi cần.</p></div><div class="trash-list">${trash.map(t=>`<div class="trash-row"><div><strong>${E(t.title)}</strong><span>${E(categories[t.category])} · Đã xóa ${new Intl.DateTimeFormat('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',day:'2-digit',month:'2-digit'}).format(new Date(t.deletedAt))}</span></div><button class="btn btn-secondary btn-small" data-action="restore" data-id="${E(t.id)}">${icon('restore')}Khôi phục</button></div>`).join('')||empty('Thùng rác đang trống','Các công việc được xóa sẽ xuất hiện ở đây.',false)}</div>`);}
function helpDialog(){showDialog(`<div class="modal-head"><p class="eyebrow">TASKFLOW · V2.5</p><h2 id="dialogTitle">Bắt đầu từ một việc nhỏ.</h2></div><div class="help-content"><p>TaskFlow là không gian quản lý công việc cá nhân của <strong>Phạm Quang Huy</strong>, được xây dựng cho học phần Phát triển ứng dụng TMĐT tại UEH.</p><ol><li><strong>Thêm công việc:</strong> ghi tên, ngày dự định, hạn chót và các bước nhỏ.</li><li><strong>Chọn Top 3:</strong> bấm ngôi sao ở những việc quan trọng nhất hôm nay.</li><li><strong>Lên lịch:</strong> kéo việc vào ngày phù hợp, chọn giờ hoặc xem gợi ý kế hoạch.</li><li><strong>Tập trung:</strong> mở một phiên hẹn giờ, sau đó lưu thời gian thực tế.</li><li><strong>Nhìn lại:</strong> xem tiến độ và thời gian tập trung trong Thống kê.</li></ol><h3>Phím tắt</h3><dl class="shortcut-list"><div><dt><kbd>N</kbd></dt><dd>Thêm công việc</dd></div><div><dt><kbd>/</kbd></dt><dd>Tìm kiếm công việc</dd></div><div><dt><kbd>Esc</kbd></dt><dd>Đóng hộp thoại hoặc menu</dd></div></dl><h3>Một vài quy tắc rõ ràng</h3><p>Hôm nay gồm việc dự định làm hôm nay và việc đến hạn hôm nay chưa có ngày dự định. Mức quan trọng và mức ưu tiên là hai thông tin riêng. Hoàn thành một task lặp sẽ tạo tối đa một lần kế tiếp.</p><p>Gợi ý kế hoạch dựa trên quy tắc về hạn, ưu tiên và khoảng trống; không sử dụng dịch vụ AI. Giao diện không phụ thuộc CDN.</p><p class="rule-note">Lần chạy đầu có dữ liệu mẫu để khám phá. Bạn có thể sửa hoặc xóa các việc mẫu. Đây là ứng dụng cá nhân chạy với Node.js; dữ liệu không tự đồng bộ sang thiết bị khác.</p><div class="project-credit"><strong>Phạm Quang Huy</strong><span>MSSV 32261020149 · LHP 26C1INF50902701</span><a href="https://github.com/huypham32261020149-work" target="_blank" rel="noopener noreferrer">GitHub cá nhân</a></div></div>`);}

function updateTimer(){
  const active=state.focus.active,display=$('#timerDisplay');
  if(active){const elapsed=focusElapsed(active),left=Math.max(0,Math.ceil(active.plannedMinutes*60-elapsed));
    if(display){display.textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;$('#timerProgress')?.setAttribute('stroke-dashoffset',String(791.68*elapsed/(active.plannedMinutes*60)));}
    if(left===0&&active.status==='running'&&!state.finishing&&Date.now()>=state.nextFocusRetry)finishFocus(true);
  }
  if(state.breakUntil){const left=Math.max(0,Math.ceil((state.breakUntil-Date.now())/1000));if($('#breakMessage'))$('#breakMessage').textContent=left?`Giờ nghỉ: ${Math.floor(left/60)}:${String(left%60).padStart(2,'0')} còn lại.`:'';if(!left){state.breakUntil=0;sessionStorage.removeItem('taskflow-break');toast('Hết giờ nghỉ. Bắt đầu một khoảng tập trung mới khi bạn sẵn sàng.');}}
}
async function finishFocus(auto=false){
  const current=state.focus.active;if(!current||state.finishing)return;state.finishing=true;
  try{await api(`/focus/${current.id}/finish`,'POST',{});await refresh();toast(auto?'Bạn đã hoàn thành phiên tập trung. Dành một chút thời gian nghỉ nhé.':'Đã lưu thời gian tập trung thực tế.');}
  catch(err){showError(err);state.nextFocusRetry=Date.now()+15000;}
  finally{state.finishing=false;}
}
async function startFocus(taskId,minutes){await api('/focus/start','POST',{taskId:taskId||null,minutes:Number(minutes)});state.breakUntil=0;sessionStorage.removeItem('taskflow-break');await refresh(false);if(state.view!=='focus')location.hash='focus';else renderView();toast('Phiên tập trung đã bắt đầu.');}
async function exportData(){const data=await api('/export');const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`TaskFlow-backup-${state.today}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã tạo bản sao JSON.');}
async function importData(file){if(!file)return;if(file.size>1024*1024){toast('Tệp quá lớn. Chọn tệp JSON nhỏ hơn 1 MB.');return;}try{const data=JSON.parse(await file.text());const result=await api('/import','POST',{data});await refresh();settingsDialog();toast(`Đã nhập ${result.importedCount} công việc; bỏ qua ${result.skippedCount} ID đã có.`);}catch(err){showError(err instanceof SyntaxError?new Error('Tệp không phải JSON hợp lệ.'):err);}finally{if($('#importFile'))$('#importFile').value='';}}

const actions={
  'add':el=>openTaskForm(null,{...(el.dataset.date?{plannedDate:el.dataset.date}:{}),...(el.dataset.status?{status:el.dataset.status}:{})}),
  'edit':el=>openTaskForm(el.dataset.id),
  'close-dialog':()=>closeDialog(),
  'toggle':async el=>{const t=taskById(el.dataset.id);if(t)await patchTask(t.id,{status:t.status==='done'?'todo':'done'},t.status==='done'?'Đã mở lại công việc.':'Một việc nữa đã xong.');},
  'top':async el=>{const t=taskById(el.dataset.id);if(t)await patchTask(t.id,{topDate:t.topDate===state.today?null:state.today},t.topDate===state.today?'Đã bỏ khỏi Top 3.':'Đã chọn vào Top 3 hôm nay.');},
  'important':async el=>{const t=taskById(el.dataset.id);if(t)await patchTask(t.id,{important:!t.important},'Đã cập nhật mức quan trọng.');},
  'pick-top':()=>pickTop(),
  'pick-top-task':async el=>{await patchTask(el.dataset.id,{topDate:state.today},'Đã chọn vào Top 3 hôm nay.');closeDialog();},
  'delete':async el=>{await api(`/tasks/${el.dataset.id}`,'DELETE');closeDialog();await refresh();toast('Đã chuyển công việc vào thùng rác.',{type:'restore',id:el.dataset.id,label:'Hoàn tác'});},
  'restore':async el=>{await api(`/tasks/${el.dataset.id}/restore`,'POST',{});await refresh();if($('#dialog').open)trashDialog();toast('Đã khôi phục công việc.');},
  'add-subtask':()=>{const input=$('#newSubtask'),title=input.value.trim();if(!title)return;if(state.formSubtasks.length>=30){toast('Mỗi công việc có tối đa 30 việc nhỏ.');return;}state.formSubtasks.push({id:crypto.randomUUID(),title,done:false});$('#subtaskEditor').innerHTML=subtaskEditor();input.value='';input.focus();},
  'remove-subtask':el=>{state.formSubtasks.splice(Number(el.dataset.index),1);$('#subtaskEditor').innerHTML=subtaskEditor();},
  'week-prev':()=>{state.week=plusDays(state.week,-7);renderView();},
  'week-next':()=>{state.week=plusDays(state.week,7);renderView();},
  'week-today':()=>{state.week=monday(state.today);renderView();},
  'suggest':el=>getSuggestions(el.dataset.date),
  'suggest-planner':el=>getSuggestions(el.dataset.date,true),
  'apply-suggestions':async()=>{const ids=$$('input[name="suggestion"]:checked').map(x=>x.value);if(!ids.length){toast('Chọn ít nhất một công việc.');return;}const result=await api('/suggestions/apply','POST',{date:state.suggestionDate,taskIds:ids,token:state.suggestions?.token});if($('#dialog').open)closeDialog();await refresh();toast(`Đã xếp lịch cho ${result.appliedCount} công việc.`);},
  'focus-task':async el=>{if(state.focus.active){location.hash='focus';toast('Bạn đang có một phiên tập trung. Kết thúc phiên trước khi đổi việc.');return;}location.hash='focus';await new Promise(r=>setTimeout(r,0));if(state.view!=='focus'){state.view='focus';renderView();}$('#focusTask').value=el.dataset.id;state.focusDraft.taskId=el.dataset.id;$('#focusMinutes').focus();toast('Đã chọn công việc. Bấm Bắt đầu tập trung khi sẵn sàng.');},
  'focus-pause':async()=>{const a=state.focus.active;if(!a)return;await api(`/focus/${a.id}/pause`,'POST',{});await refresh();},
  'focus-resume':async()=>{const a=state.focus.active;if(!a)return;await api(`/focus/${a.id}/resume`,'POST',{});await refresh();},
  'focus-finish':()=>finishFocus(false),
  'focus-cancel':async()=>{const a=state.focus.active;if(!a)return;await api(`/focus/${a.id}/cancel`,'POST',{});await refresh();toast('Đã bỏ phiên, không ghi vào thống kê.');},
  'focus-preset':el=>{if($('#focusMinutes')){$('#focusMinutes').value=el.dataset.minutes;state.focusDraft.minutes=Number(el.dataset.minutes);$('#timerDisplay').textContent=`${el.dataset.minutes.padStart(2,'0')}:00`;}},
  'break':()=>{state.breakUntil=Date.now()+state.settings.breakMinutes*60000;sessionStorage.setItem('taskflow-break',String(state.breakUntil));updateTimer();toast('Đã bắt đầu thời gian nghỉ.');},
  'stats-period':el=>{state.statsDays=Number(el.dataset.days);renderView();},
  'settings':()=>settingsDialog(), 'help':()=>helpDialog(), 'trash':()=>trashDialog(),
  'export':()=>exportData(),'import':()=>$('#importFile')?.click(),
  'reload':()=>refresh(),
};

function setDrawer(open){const wasOpen=$('#sidebar').classList.contains('is-open');$('#sidebar').classList.toggle('is-open',open);$('#mobileBackdrop').hidden=!open;$('#menuToggle').setAttribute('aria-expanded',String(open));document.body.classList.toggle('drawer-open',open);$('.workspace').inert=open;$('#sidebar').inert=!open&&window.matchMedia('(max-width:760px)').matches;if(open)$('#sidebarClose').focus();else if(wasOpen)$('#menuToggle').focus();}
function route(){const name=location.hash.slice(1);state.view=Object.hasOwn(viewNames,name)?name:'today';setDrawer(false);if(state.today)renderView();window.scrollTo(0,0);}
function globalSearch(){closeIfOpen();if(state.view!=='all'){location.hash='all';setTimeout(()=>$('#taskSearch')?.focus(),0);}else $('#taskSearch')?.focus();}
function closeIfOpen(){if($('#dialog').open)closeDialog();}
function bindEvents(){
  $('.skip-link').addEventListener('click',event=>{event.preventDefault();$('#main').focus();});
  window.matchMedia('(max-width:760px)').addEventListener('change',()=>setDrawer(false));
  $('#addTask').addEventListener('click',()=>openTaskForm());
  $('#dialogClose').addEventListener('click',closeDialog);
  $('#dialog').addEventListener('click',event=>{if(event.target===$('#dialog')){const rect=$('#dialog').getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)closeDialog();}});
  $('#dialog').addEventListener('close',()=>{activeDialogTask=null;});
  $('#settingsButton').addEventListener('click',()=>{setDrawer(false);settingsDialog();});
  $('#helpButton').addEventListener('click',()=>{setDrawer(false);helpDialog();});
  $('#globalSearch').addEventListener('click',globalSearch);
  $('#menuToggle').addEventListener('click',()=>setDrawer(!$('#sidebar').classList.contains('is-open')));
  $('#sidebarClose').addEventListener('click',()=>setDrawer(false));$('#mobileBackdrop').addEventListener('click',()=>setDrawer(false));
  window.addEventListener('hashchange',route);
  document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const action=actions[el.dataset.action];if(!action)return;try{el.disabled=true;await action(el);}catch(err){showError(err);}finally{if(el.isConnected)el.disabled=false;}});
  document.addEventListener('input',event=>{const t=event.target;if(t.id==='taskSearch'){state.filters.query=t.value;renderFiltered();}if(t.id==='quickInput')state.quickDraft=t.value;if(t.dataset.subTitle!==undefined)state.formSubtasks[Number(t.dataset.subTitle)].title=t.value;if(t.id==='focusMinutes'&&!state.focus.active&&Number(t.value)>0&&Number(t.value)<=120){state.focusDraft.minutes=Number(t.value);$('#timerDisplay').textContent=`${String(t.value).padStart(2,'0')}:00`;}});
  document.addEventListener('change',async event=>{const t=event.target;try{if(t.id==='focusTask')state.focusDraft.taskId=t.value;if(t.dataset.filter){state.filters[t.dataset.filter]=t.value;renderFiltered();}if(t.dataset.subCheck!==undefined)state.formSubtasks[Number(t.dataset.subCheck)].done=t.checked;if(t.dataset.taskStatus){t.disabled=true;await patchTask(t.dataset.taskStatus,{status:t.value});}if(t.id==='importFile')await importData(t.files[0]);}catch(err){showError(err);if(t.dataset.taskStatus){t.disabled=false;t.value=taskById(t.dataset.taskStatus)?.status||'todo';}}});
  document.addEventListener('submit',async event=>{const form=event.target;if(!['taskForm','quickAddForm','settingsForm','focusStartForm'].includes(form.id))return;event.preventDefault();if(form.id==='taskForm'){await submitTask(form);return;}const button=$('[type="submit"]',form);button.disabled=true;try{if(form.id==='quickAddForm'){const preview=await api('/quick-add/preview','POST',{text:$('#quickInput').value});openTaskForm(null,preview.task,preview);}if(form.id==='settingsForm'){const fd=new FormData(form);await api('/settings','PATCH',{name:fd.get('name').trim(),dailyCapacityMinutes:Number(fd.get('dailyCapacityMinutes')),dayStart:fd.get('dayStart'),dayEnd:fd.get('dayEnd'),focusMinutes:Number(fd.get('focusMinutes')),breakMinutes:Number(fd.get('breakMinutes'))});if(form.isConnected)closeDialog();await refresh();toast('Đã lưu nhịp làm việc của bạn.');}if(form.id==='focusStartForm')await startFocus($('#focusTask').value,$('#focusMinutes').value);}catch(err){if(form.id==='settingsForm'&&form.isConnected){const box=$('#settingsError',form);box.textContent=err.message;box.hidden=false;}else showError(err);}finally{if(button.isConnected)button.disabled=false;}});
  document.addEventListener('keydown',event=>{if(event.key==='Escape')setDrawer(false);if(event.key==='Tab'&&$('#sidebar').classList.contains('is-open')){const items=$$('a,button',$('#sidebar')).filter(el=>el.getClientRects().length&&!el.disabled);const first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}if(event.target.id==='newSubtask'&&event.key==='Enter'){event.preventDefault();actions['add-subtask']();return;}if(event.ctrlKey||event.metaKey||event.altKey||$('#dialog').open||event.target.matches('input,textarea,select,[contenteditable]'))return;if(event.key.toLowerCase()==='n'){event.preventDefault();openTaskForm();}if(event.key==='/'){event.preventDefault();globalSearch();}});
  document.addEventListener('dragstart',event=>{const item=event.target.closest('[data-drag-id]');if(!item)return;event.dataTransfer.setData('text/plain',item.dataset.dragId);event.dataTransfer.effectAllowed='move';item.classList.add('is-dragging');});
  document.addEventListener('dragend',()=>{$$('.is-dragging,.drop-active').forEach(el=>el.classList.remove('is-dragging','drop-active'));});
  document.addEventListener('dragover',event=>{const zone=event.target.closest('[data-drop-status],[data-drop-date]');if(!zone)return;event.preventDefault();event.dataTransfer.dropEffect='move';$$('.drop-active').forEach(el=>{if(el!==zone)el.classList.remove('drop-active');});zone.classList.add('drop-active');});
  document.addEventListener('dragleave',event=>{const zone=event.target.closest('[data-drop-status],[data-drop-date]');if(zone&&!zone.contains(event.relatedTarget))zone.classList.remove('drop-active');});
  document.addEventListener('drop',async event=>{const zone=event.target.closest('[data-drop-status],[data-drop-date]');if(!zone)return;event.preventDefault();zone.classList.remove('drop-active');const id=event.dataTransfer.getData('text/plain'),t=taskById(id);if(!t||t.deletedAt)return;try{if(zone.dataset.dropStatus)await patchTask(id,{status:zone.dataset.dropStatus});else if(zone.dataset.dropDate&&zone.dataset.dropDate!==t.plannedDate)await patchTask(id,{plannedDate:zone.dataset.dropDate,scheduledTime:null},'Đã chuyển ngày dự định. Bạn có thể đặt lại giờ bắt đầu.');}catch(err){showError(err);}});
}

async function init(){
  bindEvents();route();
  try{state.breakUntil=Number(sessionStorage.getItem('taskflow-break')||0);}catch{}
  try{await refresh();}catch(err){$('#content').innerHTML=`<div class="error-panel"><p class="eyebrow">CHƯA KẾT NỐI ĐƯỢC</p><h1>Mở TaskFlow cùng máy chủ.</h1><p>${E(err.message)}</p><p>Chạy <code>node server.js</code> trong thư mục ứng dụng, sau đó mở <code>http://localhost:8080</code>.</p><button class="btn btn-primary" data-action="reload">Kết nối lại</button></div>`;}
  setInterval(updateTimer,500);
  // Refresh cross-tab edits without interrupting an input or an open dialog.
  setInterval(async()=>{if(!state.today||document.hidden||$('#dialog').open||document.activeElement?.matches('input,textarea,select'))return;try{const old=JSON.stringify([state.tasks,state.focus,state.settings]),oldDate=state.today;await refresh(false);if(oldDate!==state.today){state.suggestions=null;state.week=monday(state.today);}if(old!==JSON.stringify([state.tasks,state.focus,state.settings])||oldDate!==state.today)renderView();}catch{}},15000);
  document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.today&&!$('#dialog').open)refresh().catch(()=>{});});
}
init();
